// Writes test/typecheck.ts: every JSON-RPC docs example marked "ok" in ../fixtures,
// assigned to the generated types. `tsc` then fails if an example is missing a required
// field or has a field of the wrong type. Run by `npm test` before compiling.
import { readFileSync, writeFileSync } from "node:fs";

const read = (path) => JSON.parse(readFileSync(new URL(path, import.meta.url)));

const out = [
  "// Code generated by make_typecheck.mjs. DO NOT EDIT.",
  'import Monerod from "../src/monerod";',
  'import WalletRpc from "../src/walletrpc";',
  "",
  "type Result<C, M extends keyof C> = C[M] extends (...a: any[]) => Promise<infer T> ? T : never;",
  "type Params<C, M extends keyof C> = C[M] extends (...a: infer A) => any ? A : never;",
  "",
];

// The generated methods take params positionally, in schema order, even for by-name methods.
export function argsFor(method, params) {
  if (Array.isArray(params)) return params;
  const args = method.params.map((p) => params?.[p.name]);
  while (args.length && args.at(-1) === undefined) args.pop();
  return args;
}

const literal = (args) =>
  "[" + args.map((a) => (a === undefined ? "undefined" : JSON.stringify(a))).join(", ") + "]";

function main() {
  let count = 0;
  for (const [cls, fixture, schema] of [
    ["Monerod", "../../fixtures/daemon.json", "../../../schemas/daemon.openrpc.json"],
    ["WalletRpc", "../../fixtures/wallet.json", "../../../schemas/wallet.openrpc.json"],
  ]) {
    const methods = new Map(read(schema).methods.map((m) => [m.name, m]));
    for (const c of read(fixture).cases) {
      const m = methods.get(c.name);
      if (c.protocol !== "json-rpc" || c.status !== "ok" || !m) continue;
      const value = c.known_json ?? c.json;
      const id = `${cls}_${c.name}_${c.kind}`;
      if (c.kind === "response") {
        out.push(`export const ${id}: Result<${cls}, "${c.name}"> = ${JSON.stringify(value)};`);
      } else if (c.kind === "request") {
        out.push(`export const ${id}: Params<${cls}, "${c.name}"> = ${literal(argsFor(m, value))};`);
      } else {
        continue;
      }
      count++;
    }
  }

  writeFileSync(new URL("typecheck.ts", import.meta.url), out.join("\n") + "\n");
  console.log(`test/typecheck.ts: ${count} docs examples to type-check`);
}

if (import.meta.url === `file://${process.argv[1]}`) main();
